import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:yaml/yaml.dart';

import '../project_layout.dart';
import 'deploy_target.dart';
import 'kamal_contract.dart';
import 'kamal_images.dart';
import 'kamal_secret_files.dart';
import 'stack.dart';

const kamalGeneratedHeader =
    '# generated by `dartway deploy kamal` — change deploy/config.yaml and regenerate\n';

/// The Kamal release this contract is written for and validated against.
const kamalVersion = '2.12.0';

/// Generates the deployment contract from the project, without reading secrets.
///
/// The contract names no environment. Each service has one configuration,
/// `deploy/kamal/<service>.yml`, whose host, SSH user, domains and component
/// modes are read through ERB from [DwStudioVariables] when Studio deploys;
/// `deploy/studio.yml` says what an environment must give. Kamal's
/// destination is the environment's name, so every name Kamal derives from it
/// stays what it was when environments were destination files.
class DwKamalGenerator {
  DwKamalGenerator(this.projectRoot);

  final Directory projectRoot;

  /// The project half of the contract, from `deploy/config.yaml > kamal`.
  late final DwKamalProject project = DwKamalProject.load(projectRoot);

  Map<String, String> render() {
    final snippets = Directory(p.join(projectRoot.path, 'deploy/nginx.d'));
    if (snippets.existsSync() &&
        snippets
            .listSync(recursive: true)
            .whereType<File>()
            .any((file) => file.path.endsWith('.conf'))) {
      throw StateError(
        'Native Kamal cannot apply deploy/nginx.d snippets. '
        'Move call quotas to DwServerSettings.callRateLimits and migrate '
        'other ingress policies before generating Kamal configuration.',
      );
    }
    final layout = ProjectLayout.detect(projectRoot);
    final project = this.project;
    final owner = githubOwner(project.repo);
    final contract = DwKamalContract(project.projectName);
    final services = contract.services(storage: project.storage);
    DwStack stack(DwDatabaseMode database, DwStorageMode storage) => DwStack(
      target: DwDeployTarget(
        environment: _variable(_environment),
        host: _variable(_host),
        sshUser: _variable(_sshUser),
        deployUser: project.deployUser,
        os: 'ubuntu',
        repo: project.repo,
        branch: '',
        sslEmail: '',
        apiDomain: _variable(_domain('api')),
        appDomain: _variable(_domain('app')),
        project: project.projectName,
        database: database,
        storage: storage,
        storageDomain: storage == DwStorageMode.bundled
            ? _variable(_domain('files'))
            : null,
        requiredSecrets: project.requiredSecrets,
        requiredSecretFiles: project.requiredSecretFiles,
        trustedProxyNetworks: [_variable(_trustedNetworks)],
      ),
      projectRoot: projectRoot,
      serverPackage: layout.serverPackage,
      flutterPackage: layout.flutterPackage,
    );

    final base = stack(DwDatabaseMode.external, DwStorageMode.none);
    final bundledDatabase = stack(DwDatabaseMode.bundled, DwStorageMode.none);
    final bundledStorage = stack(
      DwDatabaseMode.external,
      DwStorageMode.bundled,
    );
    Map<String, String> beyond(DwStack stack) => {
      for (final MapEntry(:key, :value) in stack.serverEnvironment.entries)
        if (!base.serverEnvironment.containsKey(key)) key: value,
    };
    final environment = _variable(_environment);
    final databaseClear = {
      ...beyond(bundledDatabase),
      DwStack.databaseHostKey: contract.postgres(environment),
    };
    final storageClear = {
      ...beyond(bundledStorage),
      'DW_STORAGE_PROVISION': 'true',
    };
    const externalStorageValues = [DwStack.storageEndpointKey];
    const externalStorageOptional = [
      DwStack.storagePublicBucketKey,
      DwStack.storagePublicBaseUrlKey,
      DwStack.storagePrivateBucketKey,
      DwStack.storageRegionKey,
      DwStack.storagePathStyleKey,
    ];
    const values = [DwStack.trustedProxyNetworksKey];

    final contractNames = {
      ...base.serverEnvironment.keys,
      ...databaseClear.keys,
      if (project.storage) ...storageClear.keys,
      if (project.storage) ...externalStorageValues,
      if (project.storage) ...externalStorageOptional,
      DwStack.allowedOriginsKey,
    };
    final clashing = project.requiredSecrets.where(contractNames.contains);
    if (clashing.isNotEmpty) {
      throw StateError(
        'deploy/config.yaml > requires > secrets: ${clashing.join(', ')} '
        '${clashing.length == 1 ? 'is a name' : 'are names'} the Kamal '
        'contract already provides — derived in env.clear, a non-secret value '
        'of the environment, or a secret of an external component '
        '(deploy/studio.yml > components). Remove '
        '${clashing.length == 1 ? 'it' : 'them'} from requires.secrets.',
      );
    }

    List<String> secrets(DwStack stack) => stack.requiredSecretKeys;
    List<String> minus(List<String> from, Iterable<String> remove) => [
      for (final name in from)
        if (!remove.contains(name)) name,
    ];
    final databaseBundledSecrets = secrets(bundledDatabase);
    final databaseExternalSecrets = secrets(base);
    final commonSecrets = [
      for (final name in databaseBundledSecrets)
        if (databaseExternalSecrets.contains(name)) name,
    ];
    final databaseBundledOnly = minus(databaseBundledSecrets, commonSecrets);
    final databaseExternalOnly = minus(databaseExternalSecrets, commonSecrets);
    final storageBundledSecrets = minus(
      secrets(stack(DwDatabaseMode.bundled, DwStorageMode.bundled)),
      databaseBundledSecrets,
    );
    final storageExternalSecrets = minus(
      secrets(stack(DwDatabaseMode.bundled, DwStorageMode.external)),
      [...databaseBundledSecrets, ...externalStorageValues],
    );
    final storageCommonSecrets = [
      for (final name in storageBundledSecrets)
        if (storageExternalSecrets.contains(name)) name,
    ];

    final files = <String, String>{};
    void yaml(String path, Map<Object, Object?> data, {bool erb = true}) {
      final body = _yaml(data);
      files[path] =
          '$kamalGeneratedHeader${erb ? _preamble(body, path) : ''}$body';
    }

    for (final service in services) {
      final identity = contract.identity(service);
      final served = base;
      yaml('deploy/kamal/$service.yml', {
        'service': identity,
        'image': '$owner/$identity',
        'minimum_version': kamalVersion,
        'servers': {
          DwKamalContract.role: {
            'hosts': [served.target.host],
            if (service == 'storage') 'cmd': '/data',
          },
        },
        'ssh': {'user': served.target.sshUser},
        'proxy': {
          'ssl': true,
          'hosts': [
            switch (service) {
              'api' => served.target.apiDomain,
              'web' => served.target.appDomain,
              _ => _variable(_domain('files')),
            },
          ],
          // The app host reaches this ingress through its nginx. Preserve that
          // chain and let the server stop at the first untrusted peer. The
          // proxy still appends the actual TCP peer to direct API requests.
          if (service == 'api') 'forward_headers': true,
          'run': {
            'version': DwKamalContract.proxyVersion,
            'options': {'sysctl': 'net.ipv4.tcp_congestion_control=bbr'},
          },
          'app_port': DwKamalContract.appPort(service),
          'healthcheck': {'path': service == 'web' ? '/' : '/health'},
          'buffering': {'requests': false, 'responses': false},
        },
        'registry': {
          'server': 'ghcr.io',
          'username': owner,
          'password': ['KAMAL_REGISTRY_PASSWORD'],
        },
        'builder': {
          'arch': 'amd64',
          'dockerfile': switch (service) {
            'api' => '${layout.serverPackage}/Dockerfile',
            'web' => '${layout.flutterPackage}/Dockerfile',
            _ => 'deploy/kamal/storage/Dockerfile',
          },
          'context': service == 'storage' ? 'deploy/kamal/storage' : '.',
        },
        'deploy_timeout': 30,
        'drain_timeout': 30,
        'retain_containers': 5,
        if (service == 'storage')
          'volumes': [contract.storageVolume(environment)],
        if (service == 'api' && project.requiredSecretFiles.isNotEmpty) ...{
          'hooks_path': kamalApiHooksDirectory,
          'volumes': [
            for (final name in project.requiredSecretFiles)
              '${project.runtimeConfigDir}/$name:'
                  '${DwStack.secretFilesDir}/$name:ro',
          ],
        },
        if (service == 'api')
          'env': {
            'clear': {
              ...base.serverEnvironment,
              DwStack.allowedOriginsKey: base.appOrigin,
              _If('bundled_database'): databaseClear,
              if (project.storage) ...{
                _If('bundled_storage'): storageClear,
                _If('!bundled_storage'): {
                  for (final name in externalStorageValues)
                    name: _Ruby('value.call(${_rubyString(name)})'),
                  for (final name in externalStorageOptional)
                    _If('ENV.key?(${_rubyString(name)})'): {
                      name: _Ruby('ENV.fetch(${_rubyString(name)})'),
                    },
                },
              },
            },
            'secret': [
              ...commonSecrets,
              if (project.storage) ...storageCommonSecrets,
              _IfItems('bundled_database', databaseBundledOnly),
              _IfItems('!bundled_database', databaseExternalOnly),
              if (project.storage) ...[
                _IfItems(
                  'bundled_storage',
                  minus(storageBundledSecrets, storageCommonSecrets),
                ),
                _IfItems(
                  '!bundled_storage',
                  minus(storageExternalSecrets, storageCommonSecrets),
                ),
              ],
            ],
          },
        if (service == 'api')
          _If('bundled_database'): {
            'accessories': {
              'postgres': {
                'service': contract.postgres(environment),
                'image': DwStack.postgresImage,
                'host': served.target.host,
                'env': {
                  'clear': {
                    'POSTGRES_DB': base.databaseName,
                    'POSTGRES_USER': base.databaseName,
                  },
                  'secret': [
                    'POSTGRES_PASSWORD:${DwStack.databasePasswordKey}',
                  ],
                },
                'directories': ['postgres:/var/lib/postgresql/data'],
              },
            },
          },
        if (service == 'web')
          'env': {
            'clear': {'DW_API_ORIGIN': base.apiOrigin},
          },
        if (service == 'storage')
          'env': {
            'clear': {'RUSTFS_CONSOLE_ENABLE': 'false'},
            'secret': [
              'RUSTFS_ACCESS_KEY:${DwStack.storageAccessKey}',
              'RUSTFS_SECRET_KEY:${DwStack.storageSecretKey}',
            ],
          },
      });
    }
    if (project.requiredSecretFiles.isNotEmpty) {
      files[kamalSecretFilesHookPath] = kamalSecretFilesHook(
        kamalGeneratedHeader,
      );
    }
    if (services.contains('storage')) {
      files['deploy/kamal/storage/Dockerfile'] =
          '${kamalGeneratedHeader}FROM ${DwStack.storageImage}\n';
    }
    final manifest = DwKamalManifest(
      project: project.projectName,
      services: services,
      ingress: [
        const DwKamalIngress(point: 'api', service: 'api'),
        const DwKamalIngress(point: 'app', service: 'web'),
        if (project.storage)
          const DwKamalIngress(
            point: 'files',
            service: 'storage',
            component: 'storage',
          ),
      ],
      components: [
        DwKamalComponent(
          name: 'database',
          provider: const {'service': 'api', 'accessory': 'postgres'},
          bundled: DwKamalNeeds(secrets: databaseBundledOnly),
          external: DwKamalNeeds(secrets: databaseExternalOnly),
        ),
        if (project.storage)
          DwKamalComponent(
            name: 'storage',
            provider: const {'service': 'storage'},
            bundled: DwKamalNeeds(secrets: storageBundledSecrets),
            external: DwKamalNeeds(
              values: externalStorageValues,
              optionalValues: externalStorageOptional,
              secrets: storageExternalSecrets,
            ),
          ),
      ],
      values: values,
      secrets: ['KAMAL_REGISTRY_PASSWORD', ...commonSecrets],
    );
    yaml(DwKamalManifest.path, {
      'project': manifest.project,
      'services': manifest.services,
      'environment': {
        'name': DwStudioVariables.environment,
        'host': DwStudioVariables.host,
        'ssh_user': DwStudioVariables.sshUser,
      },
      'kamal': {
        'version': kamalVersion,
        'config': 'deploy/kamal/{service}.yml',
        'destination': '{env}',
        // Kamal 2.12 reads `<config>.<destination>.yml` for `-d` and refuses
        // a missing one. Everything is in the service's config, so the runner
        // writes this empty map when the file is absent; it is never committed.
        'destination_config': {
          'path': 'deploy/kamal/{service}.{env}.yml',
          'content': '{}',
        },
      },
      'ingress': {
        for (final point in manifest.ingress) point.point: point.toYaml(),
      },
      'components': {
        for (final component in manifest.components)
          component.name: component.toYaml(),
      },
      'values': manifest.values,
      'secrets': manifest.secrets,
      if (project.requiredSecretFiles.isNotEmpty)
        'secret_files': {
          'directory': project.runtimeConfigDir,
          'names': project.requiredSecretFiles,
        },
      'secrets_import': contract.secretsImport('{env}'),
      'health': '/health',
      'migrations': [
        '${layout.serverPackage}/lib/src/migrations/**',
        '${layout.serverPackage}/pubspec.lock',
      ],
      'check': {
        'image': 'ghcr.io/dartway/dartway-check:${checkImageTag(layout)}',
        'args': [
          '--project',
          '/project',
          '--env',
          '{env}',
          '--version',
          '{version}',
        ],
        // The outside probe reads only where the environment answers.
        'environment': [
          for (final point in manifest.ingress) point.variable,
          if (project.storage) DwStudioVariables.bundled('storage'),
        ],
      },
    }, erb: false);
    files['.github/workflows/images.yml'] =
        '$kamalGeneratedHeader${kamalImagesWorkflow(layout, services, '$owner/${project.projectName}')}';
    return files;
  }

  /// Returns every missing, modified or obsolete generated file; never writes
  /// in check mode, including to a read-only mounted project.
  List<String> generate({bool check = false}) {
    final files = render();
    final obsolete = <String>[];
    final directory = Directory(p.join(projectRoot.path, 'deploy/kamal'));
    if (directory.existsSync()) {
      for (final file
          in directory.listSync(recursive: true).whereType<File>()) {
        final relative = p.relative(file.path, from: projectRoot.path);
        if (!files.containsKey(relative) &&
            _isGenerated(file.readAsStringSync())) {
          obsolete.add(relative);
        }
      }
    }
    final stale = <String>[...obsolete];
    for (final entry in files.entries) {
      final file = File(p.join(projectRoot.path, entry.key));
      final executable = entry.key == kamalSecretFilesHookPath;
      final current =
          file.existsSync() &&
          file.readAsStringSync() == entry.value &&
          (!executable ||
              Platform.isWindows ||
              file.statSync().mode & 0x49 != 0);
      if (current) continue;
      stale.add(entry.key);
      if (!check) {
        file.parent.createSync(recursive: true);
        file.writeAsStringSync(entry.value);
        if (executable && !Platform.isWindows) {
          final result = Process.runSync('chmod', ['755', file.path]);
          if (result.exitCode != 0) {
            throw StateError(
              'Cannot make ${entry.key} executable: ${result.stderr}',
            );
          }
        }
      }
    }
    if (!check) {
      for (final path in obsolete) {
        File(p.join(projectRoot.path, path)).deleteSync();
      }
    }
    return stale..sort();
  }

  static bool _isGenerated(String text) =>
      text.startsWith(kamalGeneratedHeader) ||
      text.startsWith('#!/usr/bin/env ruby\n$kamalGeneratedHeader');

  static String githubOwner(String repo) {
    final match = RegExp(
      r'^(?:git@github\.com:|https://github\.com/)([\w-]+)/[\w.-]+(?:\.git)?$',
    ).firstMatch(repo);
    if (match == null) {
      throw StateError(
        'deploy/config.yaml: expected a GitHub repository, got "$repo".',
      );
    }
    return match[1]!.toLowerCase();
  }

  static String checkImageTag(ProjectLayout layout) {
    final lock = File(p.join(layout.flutterPackageDir.path, 'pubspec.lock'));
    if (!lock.existsSync()) {
      throw StateError(
        '${lock.path}: resolve dartway_cli before generating Kamal configuration.',
      );
    }
    final yaml = loadYaml(lock.readAsStringSync());
    final packages = yaml is YamlMap ? yaml['packages'] : null;
    final cli = packages is YamlMap ? packages['dartway_cli'] : null;
    if (cli is! YamlMap)
      throw StateError('${lock.path}: dartway_cli is not resolved.');
    final description = cli['description'];
    switch (cli['source']) {
      case 'git':
        final sha = description is YamlMap ? description['resolved-ref'] : null;
        if (sha is String && RegExp(r'^[a-f0-9]{40}$').hasMatch(sha))
          return sha;
      case 'hosted':
        final version = cli['version'];
        if (version is String &&
            RegExp(r'^\d+\.\d+\.\d+(?:[-+][\w.+-]+)?$').hasMatch(version))
          return version;
      case 'path':
        final path = description is YamlMap ? description['path'] : null;
        if (path is String) {
          final root = p.isAbsolute(path)
              ? path
              : p.join(lock.parent.path, path);
          try {
            final projectTree = Process.runSync('git', [
              '-C',
              layout.root.path,
              'rev-parse',
              '--show-toplevel',
            ]);
            if (projectTree.exitCode == 0) {
              final tree = Directory(
                (projectTree.stdout as String).trim(),
              ).resolveSymbolicLinksSync();
              final cliPath = Directory(root).resolveSymbolicLinksSync();
              if (p.equals(tree, cliPath) || p.isWithin(tree, cliPath)) {
                throw StateError(
                  '${lock.path}: dartway_cli path dependency is inside the '
                  "project's own git work tree. A vendored framework cannot identify "
                  'a published check image. Instead, pin dartway_cli by git ref.',
                );
              }
            }
            final result = Process.runSync('git', [
              '-C',
              root,
              'rev-parse',
              'HEAD',
            ]);
            final sha = (result.stdout as String).trim();
            if (result.exitCode == 0 && RegExp(r'^[a-f0-9]{40}$').hasMatch(sha))
              return sha;
          } on FileSystemException {
            // A missing resolved path gets the same named lock diagnostic.
          } on ProcessException {
            // The caller reports the same named resolution failure as a
            // missing checkout or HEAD, rather than a process stack trace.
          }
        }
    }
    throw StateError(
      '${lock.path}: cannot resolve a check image tag for dartway_cli (${cli['source']}).',
    );
  }
}

/// The names Kamal derives from a project, one place for the generator and
/// the native checks: what the configuration says and what the checks look
/// for on a server are the same strings.
class DwKamalContract {
  const DwKamalContract(this.projectName);

  final String projectName;

  /// The one role of every service.
  static const role = 'web';

  static const proxyVersion = 'v0.10.2';

  /// Deploy order. Storage is a service of its own, deployed only where the
  /// environment bundles it.
  List<String> services({required bool storage}) => [
    if (storage) 'storage',
    'api',
    'web',
  ];

  /// The services an environment of [target]'s modes runs.
  List<String> servicesOf(DwDeployTarget target, {required bool storage}) => [
    for (final service in services(storage: storage))
      if (service != 'storage' || target.storage == DwStorageMode.bundled)
        service,
  ];

  String identity(String service) => '$projectName-$service';

  static int appPort(String service) => switch (service) {
    'api' => 8080,
    'storage' => 9000,
    _ => 80,
  };

  /// The bundled Postgres accessory of [environment].
  String postgres(String environment) =>
      '${identity('api')}-postgres-$environment';

  /// The bundled storage's data volume in [environment].
  String storageVolume(String environment) =>
      '${identity('storage')}-data-$environment:/data';

  /// The API's Kamal env file on the host, relative to the SSH user's home
  /// (`/root` for root): where an environment's secret values already live.
  String secretsImport(String environment) =>
      '~/.kamal/apps/${identity('api')}-$environment/env/roles/$role.env';
}

const _hostPattern =
    r'/\A(?=.{1,253}\z)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+'
    r'[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\z/';

/// What each Ruby variable of a configuration reads, in dependency order.
/// Only what the body uses is defined, so a file asks Studio for no variable
/// it does not read.
const _definitions = <String, String>{
  'environment':
      r"  environment = valid.call('STUDIO_ENVIRONMENT', /\A[a-z0-9][a-z0-9_-]*\z/)"
      '\n'
      r"  unless ENV['KAMAL_DESTINATION'] == environment"
      '\n'
      r'    raise "Run Kamal with -d #{environment}: the destination is STUDIO_ENVIRONMENT."'
      '\n'
      '  end\n',
  'bundled_database':
      r"  bundled_database = valid.call('STUDIO_BUNDLED_DATABASE', /\A(?:true|false)\z/) == 'true'"
      '\n',
  'bundled_storage':
      r"  bundled_storage = valid.call('STUDIO_BUNDLED_STORAGE', /\A(?:true|false)\z/) == 'true'"
      '\n',
  'host':
      r"  host = valid.call('STUDIO_HOST', /\A[A-Za-z0-9.:\[\]-]+\z/)"
      '\n',
  'ssh_user':
      r"  ssh_user = valid.call('STUDIO_SSH_USER', /\A[A-Za-z_][A-Za-z0-9_.-]*\z/)"
      '\n',
  'domain_api':
      "  domain_api = valid.call('STUDIO_DOMAIN_API', $_hostPattern)\n",
  'domain_app':
      "  domain_app = valid.call('STUDIO_DOMAIN_APP', $_hostPattern)\n",
  'domain_files':
      "  domain_files = bundled_storage ? "
      "valid.call('STUDIO_DOMAIN_FILES', $_hostPattern) : nil\n",
  'trusted_proxy_networks':
      r"  trusted_proxy_networks = valid.call('DW_TRUSTED_PROXY_NETWORKS', /\A[0-9A-Fa-f.:\/]+(?:,[0-9A-Fa-f.:\/]+)*\z/)"
      '\n',
};

/// The ERB block that reads and validates the environment's variables before
/// any of them reaches the YAML. A missing or malformed variable stops Kamal
/// with its name, rather than deploying an empty host.
String _preamble(String body, String path) {
  final storage = path.endsWith('/storage.yml');
  final used = <String>{
    'environment',
    for (final tag in RegExp(r'<%=?(.*?)-?%>').allMatches(body))
      ...RegExp(r'[a-z_]+').allMatches(tag[1]!).map((match) => match[0]!),
    if (storage) 'bundled_storage',
  };
  if (used.contains('domain_files')) used.add('bundled_storage');
  return [
    '<%\n',
    "  require 'json'\n",
    '  value = lambda do |name|\n',
    '    found = ENV[name].to_s\n',
    r'    raise "#{name} is not set: Studio sets it for the environment it deploys (deploy/studio.yml)." if found.empty?',
    '\n',
    '    found\n',
    '  end\n',
    '  valid = lambda do |name, pattern|\n',
    '    found = value.call(name)\n',
    r'    raise "#{name} is not valid: #{found.inspect}." unless found.match?(pattern)',
    '\n',
    '    found\n',
    '  end\n',
    for (final MapEntry(:key, :value) in _definitions.entries)
      if (used.contains(key)) value,
    if (storage) ...[
      r'  raise "Storage is external in #{environment}: deploy this service only where STUDIO_BUNDLED_STORAGE is true." unless bundled_storage',
      '\n',
    ],
    '-%>\n',
  ].join();
}

/// A Ruby expression, rendered as a JSON string by ERB.
final class _Ruby {
  const _Ruby(this.expression);
  final String expression;
}

/// A map key: its value, a map, is spliced in only where [condition] holds.
final class _If {
  _If(this.condition);
  final String condition;
}

/// List items present only where [condition] holds.
final class _IfItems {
  const _IfItems(this.condition, this.items);
  final String condition;
  final List<Object?> items;
}

const _environment = 'environment';
const _host = 'host';
const _sshUser = 'ssh_user';
const _trustedNetworks = 'trusted_proxy_networks';
String _domain(String point) => 'domain_$point';

/// A placeholder for a value of the environment, carried through the shared
/// derivations of [DwStack] and turned into a Ruby variable when written.
String _variable(String name) => '\u0001$name\u0001';
final _variables = RegExp('\u0001(\\w+)\u0001');

String _rubyString(String text) =>
    "'${text.replaceAll(r'\', r'\\').replaceAll("'", r"\'")}'";

/// [text] as a Ruby expression when it carries placeholders, otherwise null.
String? _rubyOf(String text) {
  if (!_variables.hasMatch(text)) return null;
  final parts = <String>[];
  var at = 0;
  for (final match in _variables.allMatches(text)) {
    if (match.start > at)
      parts.add(_rubyString(text.substring(at, match.start)));
    parts.add(match[1]!);
    at = match.end;
  }
  if (at < text.length) parts.add(_rubyString(text.substring(at)));
  return parts.join(' + ');
}

String _scalar(Object? value) => switch (value) {
  _Ruby(:final expression) => '<%= ($expression).to_json %>',
  final String text => switch (_rubyOf(text)) {
    final expression? => '<%= ($expression).to_json %>',
    null => jsonEncode(text),
  },
  final List<Object?> items => '[${items.map(_scalar).join(',')}]',
  final Map<Object?, Object?> map when map.isEmpty => '{}',
  _ => jsonEncode(value),
};

String _yaml(Map<Object, Object?> map, [int depth = 0]) {
  final indent = '  ' * depth;
  final out = StringBuffer();
  for (final MapEntry(:key, :value) in map.entries) {
    if (key is _If) {
      out
        ..writeln('<% if ${key.condition} -%>')
        ..write(_yaml(value! as Map<Object, Object?>, depth))
        ..writeln('<% end -%>');
      continue;
    }
    out.write('$indent$key:');
    if (value case final Map<Object, Object?> nested when nested.isNotEmpty) {
      out.writeln();
      out.write(_yaml(nested, depth + 1));
    } else if (value case final List<Object?> items
        when items.any((item) => item is _IfItems)) {
      out.writeln();
      void write(Object? item) {
        if (item is _IfItems) {
          if (item.items.isEmpty) return;
          out.writeln('<% if ${item.condition} -%>');
          item.items.forEach(write);
          out.writeln('<% end -%>');
        } else {
          out.writeln('$indent  - ${_scalar(item)}');
        }
      }

      items.forEach(write);
    } else {
      out.writeln(' ${_scalar(value)}');
    }
  }
  return out.toString();
}
